    server, client = yield self.make_iostream_pair(max_buffer_size=total_bytes)

    @gen.coroutine
    def produce():
        data = b'x' * m
        for i in range(n):
            yield server.write(data)

    @gen.coroutine
    def consume():
        nread = 0
        while nread < total_bytes:
            res = yield client.read_bytes(m)
            nread += len(res)

    try:
        yield [produce() for i in range(nproducers)] + [consume()]
    finally:
        server.close()
        client.close()

